136	): Promise<string | null> {
137	  if (!stripeConfigured() || cardCents <= 0) return null;
138	  const base = process.env.APP_URL ?? "http://localhost:3000";
139	  const session = await stripe().checkout.sessions.create({
140	    mode: "payment",
141	    customer_email: user.email,
142	    line_items: [
143	      {
144	        price_data: {
145	          currency: "usd",
146	          product_data: { name: `Nxeon VPS upgrade${resize.planName ? ` — ${resize.planName}` : ""}` },
147	          unit_amount: cardCents,
148	        },
149	        quantity: 1,
150	      },
151	    ],
152	    metadata: {
153	      nxeonUserId: user.id,
154	      // chargeCents = the FULL proration to debit on confirm (not the card amount).
155	      nxeonResize: packMetadata("Resize intent", {
156	        serverId: resize.serverId,
157	        planId: resize.planId,
158	        chargeCents: resize.prorateCents,
159	      }),
