215	/**
216	 * A cents amount that arrived from OUTSIDE this process (Stripe metadata) and is
217	 * about to be handed to `debitWallet`. Integer, non-negative, finite — anything
218	 * else is refused rather than coerced, for the same reason `parseOrderPrice`
219	 * refuses a half-valid price: the caller's `?? quote.prorateCents` fallback would
220	 * silently RE-PRICE the purchase at confirm time, which is the H2 incident.
221	 */
222	function parseChargeCents(raw: unknown): number | null {
223	  if (typeof raw !== "number" || !Number.isInteger(raw) || raw < 0) return null;
224	  return raw;
225	}
226	
227	function parseId(raw: unknown): string | null {
228	  return typeof raw === "string" && raw.length > 0 ? raw : null;
229	}
