327	/**
328	 * Retrieve a Checkout session ONCE. Throws when Stripe cannot be read — the caller
329	 * must never be able to mistake a transport failure for "this session is a top-up".
330	 */
331	export async function retrieveCheckoutSession(sessionId: string): Promise<Stripe.Checkout.Session> {
332	  if (!stripeConfigured()) throw new Error("Stripe is not configured");
333	  return stripe().checkout.sessions.retrieve(sessionId);
334	}
335	
336	/** Retrieve + classify in one step. Throws on a Stripe read failure, never lies. */
337	export async function getCheckoutPurpose(sessionId: string): Promise<CheckoutPurpose> {
338	  return classifyCheckoutSession(await retrieveCheckoutSession(sessionId));
339	}
