1	// Shared server-upgrade (RESIZE up) core — used by the wallet flow
2	// (lib/actions-server.ts resizeServer) and by the Stripe confirm route so a paid
3	// checkout can apply the upgrade immediately. Plain server module (not "use server").
4	import { db } from "./db";
5	import { debitWallet, InsufficientBalanceError } from "./wallet";
6	import { invoiceCreateData } from "./invoices";
7	import { prorateUpgradeCents, remainingMonths } from "./proration";
8	
9	/**
10	 * Average calendar month in ms — RE-EXPORTED from lib/proration.ts, never
11	 * redeclared.
12	 *
13	 * It used to be its own `30.44 * 86400_000` here, a byte-identical twin of the one
14	 * in lib/proration.ts, and lib/disk-expand.ts imported THIS copy while every other
15	 * proration read the other. Two constants that happen to be equal are still two
16	 * constants: the day someone tunes one (to 365/12, or to a real calendar month) the
17	 * disk-expansion charge and the plan-resize charge quietly start pricing the same
18	 * remaining term differently. This file's whole history is second copies of a
19	 * number drifting, so there is one and it lives with the proration maths.
20	 */
21	export { MS_PER_AVG_MONTH } from "./proration";
22	
23	export class ResizeError extends Error {}
24	
25	type QuotedServer = Awaited<ReturnType<typeof loadServer>>;
26	type QuotedPlan = NonNullable<Awaited<ReturnType<typeof loadPlan>>>;
27	
28	function loadServer(serverId: string) {
29	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
30	}
31	function loadPlan(planId: string) {
32	  return db.plan.findUnique({ where: { id: planId } });
33	}
34	
35	export type ResizeQuote = {
36	  server: NonNullable<QuotedServer>;
37	  newPlan: QuotedPlan;
38	  prorateCents: number;
39	};
40	
41	/**
42	 * Validate an UPGRADE and compute the prorated charge over the ACTUAL remaining
43	 * duration (monthly price difference for every remaining month; null expiresAt
44	 * on free/admin servers => 0). Throws ResizeError with a user-facing message on
45	 * any guard failure. Does NOT check ownership — callers must do that.
46	 *
47	 * ─── INTERACTION WITH PER-SERVER EXTRA DISK ─────────────────────────────────
48	 * `Server.extraDiskGB` (disk bought via the deploy upsell or "Add storage") is
49	 * ADDITIVE to whichever plan the server is on, so a plan change must leave it
50	 * completely alone. Two things follow, and both are deliberate:
51	 *
52	 *  1. NOT DOUBLE-CHARGED. The proration below is a difference of PLAN monthly
53	 *     prices. The extra-disk surcharge is identical before and after the resize
54	 *     (same GB, same per-GB price), so it cancels out of the delta exactly — it
55	 *     must never be added here. It keeps being billed, unchanged, by the renewal
56	 *     sweep, which reads `extraDiskGB` directly.
57	 *  2. NOT LOST. Nothing in the resize path writes `extraDiskGB`, and the worker's
58	 *     RESIZE handler sizes the disk to `newPlan.diskGB + server.extraDiskGB` — so
59	 *     the customer keeps every GB they paid for. (Sizing to the bare plan disk
60	 *     would ask Proxmox to SHRINK the disk of any server holding extra storage,
61	 *     and the whole resize would hard-fail.)
62	 *
63	 * The disk-grow guard below intentionally compares PLAN disks, not effective
64	 * disks: since the extra is added to both sides, a target plan with an equal or
65	 * larger disk can never shrink the effective disk.
66	 */
67	export async function resizeQuote(serverId: string, planId: string): Promise<ResizeQuote> {
68	  const server = await loadServer(serverId);
69	  if (!server) throw new ResizeError("Not found");
70	  const newPlan = await loadPlan(planId);
71	  if (!newPlan?.active) throw new ResizeError("Plan not available.");
72	  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
73	  // A GAME server is not priced from `plan` at all, so it cannot be prorated
74	  // against it.
75	  //
76	  // Game tiers carry BOTH a base `planId` and a `gamePlanId`, and are sold at
77	  // `gamePlan.priceCents` — a FLAT, all-in price, typically LOWER than the base
78	  // plan they run on. The live row: `minecraft-mm8w85` sold at $4.99 on a Starter
79	  // base plan of $8.99. `renewalCharge` already treats a game plan as all-in with
80	  // no add-on lines; every proration path read `server.plan.priceCents` and was
81	  // blind to it.
82	  //
83	  // The dangerous direction is the CREDIT. lib/proration.ts rests on one
84	  // invariant — a prorated credit is strictly less than the cash actually
85	  // collected for those months — and that is the whole argument in
86	  // `resolveTermPromoPercent`. A tier sold at $9.99/mo flat on a $20.99 base plan
87	  // credits $20.99-worth per remaining month on a downgrade: real wallet money the
88	  // customer never paid, self-service.
89	  //
90	  // Today it is blocked only by the disk-monotonic guard below — in a catalogue
91	  // where price and disk both rise, no cheaper plan has equal-or-larger disk. That
92	  // is a coincidence of the current price list, not a protection; one cheap
93	  // high-disk plan opens it. lib/proration.ts's header calls out exactly this shape
94	  // about the pre-2026-07-25 bug, so it is refused explicitly rather than left
95	  // resting on an unrelated guard.
96	  if (server.gamePlanId) {
97	    throw new ResizeError(
98	      "Game server plans are fixed bundles — switch tiers from the game server's own settings, or contact support.",
99	    );
100	  }
101	  if (newPlan.diskGB < server.plan.diskGB) {
102	    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
103	  }
104	  if (newPlan.priceCents < server.plan.priceCents) {
105	    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
106	  }
107	  if (!["RUNNING", "STOPPED"].includes(server.status)) throw new ResizeError("Server is busy.");
108	
109	  let prorateCents = 0;
110	  if (!server.isFree && server.expiresAt) {
111	    // Price the upgrade at the term discount AND the rate THIS SERVER'S TERM WAS
112	    // SOLD AT (`server.termPromoPercent`, persisted at every point a term is
113	    // bought). Using the raw list-price delta (as this did until 2026-07-25)
114	    // overcharged by the whole discount stack: on a 36-month term with a 30% promo
115	    // running, $1,044.45 to upgrade versus $665.08 to simply buy the same plan
116	    // outright for the same end date. Pricing off `currentPromo(now)` instead (as
117	    // it did until 2026-07-26) was worse: the customer picked the rate by picking
118	    // the date, upgrading under Cyber Monday's 45% and downgrading under the 15%
119	    // Launch Sale to pocket the spread. Shared with the downgrade credit and with
120	    // the client picker via lib/proration.ts so displayed, charged and credited
121	    // cannot drift apart.
122	    //
123	    // `remainingMonths` covers EVERY month left on `expiresAt` and takes no cap —
124	    // see the note on it. Charging the full stacked duration here is what makes the
125	    // mirror-image downgrade credit safe to pay out over the same duration: after
126	    // this charge the customer has genuinely paid the new plan's rate for every one
127	    // of those months. Capping this side alone would mint money on a round trip;
128	    // capping the credit side alone destroyed $362.88 of it until 2026-07-26.
129	    prorateCents = prorateUpgradeCents({
130	      fromMonthlyCents: server.plan.priceCents,
131	      toMonthlyCents: newPlan.priceCents,
132	      termMonths: server.termMonths,
133	      termPromoPercent: server.termPromoPercent,
134	      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
135	    });
136	  }
137	  return { server, newPlan, prorateCents };
138	}
139	
140	/**
141	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
142	 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
143	 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
144	 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
145	 * unauthenticated confirm route. Throws ResizeError on any guard failure.
146	 *
147	 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
148	 * amount the customer paid into their wallet at checkout so the debit here nets to
149	 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
150	 * spend the just-credited funds). The wallet path omits it and debits the quote.
151	 */
152	export async function applyResize(opts: {
153	  serverId: string;
154	  planId: string;
155	  actorUserId: string;
156	  chargeCents?: number;
157	}): Promise<void> {
158	  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
159	  const prorateCents = opts.chargeCents ?? quoted;
160	
161	  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
162	  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");
163	
164	  try {
165	    await db.$transaction(async (tx) => {
166	      if (prorateCents > 0) {
167	        await debitWallet(tx, server.userId, prorateCents);
168	        await tx.walletTransaction.create({
169	          data: {
170	            userId: server.userId,
171	            amountCents: -prorateCents,
172	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
173	          },
174	        });
175	        // PAID invoice for the proration charge (one per user-initiated resize).
176	        await tx.invoice.create({
177	          data: invoiceCreateData({
178	            userId: server.userId,
179	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
180	            status: "PAID",
181	            lineItems: [
182	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
183	            ],
184	          }),
185	        });
186	      }
187	      // NOTE: a plan change deliberately does NOT touch `termPromoPercent`. It does
188	      // not re-base the term — `expiresAt` is untouched and no new months are sold —
189	      // it only moves the customer to a different plan at the rate they already
190	      // bought. Keeping the scalar is exactly what makes upgrade-then-downgrade net
191	      // to zero: both halves read the same stored basis. (This is also why the basis
192	      // is stored as a percent rather than a $/mo figure: a cents rate would have to
193	      // be rewritten here, and that rewrite is one more place to get it wrong.)
194	      //
195	      // Record the amount charged on the job so the worker's RESIZE handler can
196	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
197	      // resize terminally fails — money is committed here, before the job runs.
198	      await tx.job.create({
199	        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
200	      });
201	      await tx.auditLog.create({
202	        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
203	      });
204	    });
205	  } catch (e) {
206	    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
207	    throw e;
208	  }
209	}
